    # Initialize the distance and path dictionaries
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    path = {node: None for node in graph}

    # Initialize the heap with the source node
    import heapq
    heap = [(0, source)]

    while heap:
        current_distance, current_node = heapq.heappop(heap)

        # Early exit if we've reached the target node
        if current_node == target:
            path_nodes = []
            while current_node is not None:
                path_nodes.append(current_node)
                current_node = path[current_node]
            return (current_distance, path_nodes[::-1])

        # Skip if the current distance is not the current shortest
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            # Check if this path is shorter than the previously stored distance
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                path[neighbor] = current_node
                heapq.heappush(heap, (distance, neighbor))

    # If we reach this point, the target is unreachable
    return (float('inf'), None)

