    # Initialize the path to None for all nodes
    path = {target: None}

    # If the target is not in the graph, return infinity and None
    if target not in graph:
        return float("inf"), None

    # Start the search from the source to the target
    distance = shortest_distance(source, path, cached_distances)

    # If the target has an infinite distance, it means it's unreachable
    if distance == float("inf"):
        return distance, None

    # Reconstruct the path from the cached distances
    path = []
    current = target
    while current:
        path.insert(0, current)
        current = path[0]
