def shortest_path(graph, source, target):
    # Initialize the distance dictionary from the source to all other nodes
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # Initialize the previous nodes dictionary
    previous_nodes = {node: None for node in graph}

    # Priority queue to manage nodes to visit
    # We use a min-heap with a tuple (distance, node) to decide the order
    from heapq import heappush, heappop
    from collections import defaultdict
    priority_queue = [(0, source)]

    # Prim's algorithm variant for single-source shortest paths
    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # If we reached the target, we can return the path and distance
        if current_node == target:
            reconstructed_path = []
            while current_node is not None:
                reconstructed_path.append(current_node)
                current_node = previous_nodes[current_node]
            reconstructed_path.reverse()
            return (current_distance, reconstructed_path)

        # If we haven't visited the current node yet
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            # Only consider this new path if it's better than any previously known path
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heappush(priority_queue, (distance, neighbor))

    # If we've exhausted the priority queue without reaching the target, the target is unreachable
    return (float('inf'), None)
