def shortest_path(graph, source, target):
    import heapq

    # Define a custom class for Node that stores distance and path
    class Node:
        def __init__(self, distance, path):
            self.distance = distance
            self.path = path

        def __lt__(self, other):
            return self.distance < other.distance

    # Initialize the priority queue and dictionary to keep track of the shortest distance to each node
    priority_queue = []
    distance = {node: float('inf') for node in graph}
    distance[source] = 0
    heapq.heappush(priority_queue, Node(0, [source]))

    while priority_queue:
        current = heapq.heappop(priority_queue)

        if current.distance > distance[current.path[-1]]:
            continue

        if current.path[-1] == target:
            return (current.distance, current.path)

        for neighbor, weight in graph.get(current.path[-1], []):
            new_distance = current.distance + weight
            if new_distance < distance[neighbor]:
                distance[neighbor] = new_distance
                heapq.heappush(priority_queue, Node(new_distance, current.path + [neighbor]))

    return (float('inf'), None)

