def shortest_path(graph, source, target):
    # If the graph is represented as an adjacency list
    unvisited = defaultdict(lambda: float('inf'), {source: 0})
    previous = {}
    queue = [(0, source)]

    while queue:
        current_distance, current_vertex = heapq.heappop(queue)

        # If we reached the target, construct the path
        if current_vertex == target:
            path = []
            while current_vertex in previous:
                path.append(current_vertex)
                current_vertex = previous[current_vertex]
            path.append(source)
            path.reverse()
            return (current_distance, path)

        if current_distance > unvisited[current_vertex]:
            continue

        for neighbor, weight in graph.get(current_vertex, ()):
            distance = current_distance + weight

            # Only consider this new path if it's better
            if distance < unvisited[neighbor]:
                previous[neighbor] = current_vertex
                unvisited[neighbor] = distance
                heapq.heappush(queue, (distance, neighbor))

    # If we exhausted the queue without finding the target, it's unreachable
    return (float('inf'), None)

